<x-layouts.app :title="$title ?? 'Worship'" :ministry-name="$ministryName ?? null" :primary-color="$primaryColor ?? null" :accent-color="$accentColor ?? null">
    <div class="worship-shell" data-worship-shell>
        <header class="worship-header"><a href="/"><span class="worship-brand-mark">{{ mb_strtoupper(mb_substr($ministryName ?? 'M',0,1)) }}</span><strong>{{ $ministryName ?? config('app.name') }}</strong></a><div class="worship-header-actions"><div class="worship-status"><span class="worship-live-dot"></span><span>Service room</span></div><button class="workspace-theme-toggle" type="button" data-worship-theme-toggle aria-pressed="false" aria-label="Switch to dark mode"><span class="workspace-theme-track" aria-hidden="true"></span><span class="workspace-theme-label">Light</span></button></div></header>
        <main class="worship-content">{{ $slot }}</main>
    </div>
    <script>
        (() => { const shell = document.currentScript.closest('[data-worship-shell]'); const toggle = shell?.querySelector('[data-worship-theme-toggle]'); if (!shell || !toggle) return; const storageKey = 'ministry-theme'; const legacyStorageKey = 'ministry-public-theme'; const setTheme = (theme) => { const dark = theme === 'dark'; shell.classList.toggle('worship-theme-dark', dark); toggle.setAttribute('aria-pressed', String(dark)); toggle.setAttribute('aria-label', dark ? 'Switch to light mode' : 'Switch to dark mode'); const label = toggle.querySelector('.workspace-theme-label'); if (label) label.textContent = dark ? 'Dark' : 'Light'; }; const savedTheme = localStorage.getItem(storageKey) ?? localStorage.getItem(legacyStorageKey); if (savedTheme) localStorage.setItem(storageKey, savedTheme); setTheme(savedTheme === 'dark' ? 'dark' : 'light'); toggle.addEventListener('click', () => { const theme = shell.classList.contains('worship-theme-dark') ? 'light' : 'dark'; localStorage.setItem(storageKey, theme); setTheme(theme); }); window.addEventListener('storage', (event) => { if (event.key === storageKey) setTheme(event.newValue === 'dark' ? 'dark' : 'light'); }); })();
    </script>
</x-layouts.app>
